import{_ as e,o as i,c as s,a0 as a}from"./chunks/framework.Bmhw_dvp.js";const c=JSON.parse('{"title":"Rullst AI: Developing with Autonomous Agents","description":"","frontmatter":{},"headers":[],"relativePath":"guide/2-rullst-ai.md","filePath":"guide/2-rullst-ai.md"}'),n={name:"guide/2-rullst-ai.md"};function o(l,t,r,h,d,p){return i(),s("div",null,[...t[0]||(t[0]=[a('<h1 id="rullst-ai-developing-with-autonomous-agents" tabindex="-1">Rullst AI: Developing with Autonomous Agents <a class="header-anchor" href="#rullst-ai-developing-with-autonomous-agents" aria-label="Permalink to &quot;Rullst AI: Developing with Autonomous Agents&quot;">​</a></h1><p>Rullst was designed from the ground up to be the first <strong>&quot;AI-native&quot;</strong> Rust framework. What does this mean in practice?</p><p>Traditional frameworks rely heavily on runtime &quot;magic&quot; (reflection, dynamic string-based dependency injection, weak typing, and heavy metaprogramming). While this is great for humans writing short scripts, it is <strong>terrible for AI Agents</strong>, as it prevents the AI from validating whether the code is correct before running it.</p><p>In Rullst, we opted for <strong>Strong Typing and Compile-Time Guarantees</strong>. This allows the Rust compiler to act as an &quot;absolute supervisor&quot; for the AI. If the AI makes a mistake, the code won&#39;t compile, and the AI can read the detailed error and fix the problem instantly, creating a perfect feedback loop.</p><h2 id="_1-the-agent-manifesto-agents-md" tabindex="-1">1. The Agent Manifesto (<code>AGENTS.md</code>) <a class="header-anchor" href="#_1-the-agent-manifesto-agents-md" aria-label="Permalink to &quot;1. The Agent Manifesto (`AGENTS.md`)&quot;">​</a></h2><p>Every Rullst project generated via <code>cargo rullst new</code> automatically includes two vital files in the root: <code>.ai-rules</code> and <code>AGENTS.md</code>.</p><p>These are the heart of AI-assisted development. The <code>AGENTS.md</code> file acts as the &quot;Bible&quot; of your project for any autonomous agent (like Cursor, Github Copilot, Gemini, or Claude). It tells the AI exactly how it should behave in your codebase.</p><p>Example of the default content:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">1.</span><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;"> **Static Dispatch over Dynamic**</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: Prefer static dispatch (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`impl Trait`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> or generics) over </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`dyn Trait`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> to ensure explicit concrete types for AI context tracking and optimization.</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">2.</span><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;"> **Explicit APIs**</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: Avoid hidden state. Every controller and middleware should be explicit in its arguments.</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">3.</span><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;"> **HTML Macros**</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: Boolean attributes in the </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`html!`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> macro must be quoted (e.g., </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`required=&quot;true&quot;`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">).</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">4.</span><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;"> **No Panics**</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: Never use </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`unwrap()`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> or </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">`expect()`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> in production routes.</span></span></code></pre></div><h2 id="_2-rullst-s-ai-friendly-patterns" tabindex="-1">2. Rullst&#39;s AI-Friendly Patterns <a class="header-anchor" href="#_2-rullst-s-ai-friendly-patterns" aria-label="Permalink to &quot;2. Rullst&#39;s AI-Friendly Patterns&quot;">​</a></h2><p>Rullst&#39;s API was designed so that the AI rarely hallucinates:</p><ul><li><strong>Explicit Routes:</strong> The <code>routes![ ... ]</code> macro is visual and delimited. The AI knows exactly where to add a new route without having to search across scattered files.</li><li><strong>Rullst ORM:</strong> Based on Pure SQL (via SQLx) + Derives. AIs are much better at writing pure, correct SQL queries than learning an obscure query builder. Rullst takes advantage of this by using the database in a pure relational way.</li><li><strong>Clean Background Workers:</strong> The queue system does not require complex global registration; you simply create an async function.</li></ul><h2 id="_3-how-to-get-the-best-results" tabindex="-1">3. How to Get the Best Results <a class="header-anchor" href="#_3-how-to-get-the-best-results" aria-label="Permalink to &quot;3. How to Get the Best Results&quot;">​</a></h2><p>When instructing an AI to add a feature in Rullst:</p><ol><li>Ask it to <strong>read</strong> the <code>docs/spec.md</code> and <code>AGENTS.md</code> files first.</li><li>Say: &quot;Create a new Controller following the pattern established in <code>auth_controller.rs</code>&quot;. Today&#39;s AIs are brilliant at pattern matching. Rullst provides the skeleton, the AI fills in the meat.</li><li>Use the generators! Ask the AI to use <code>cargo rullst make:controller</code> in the terminal (if it&#39;s an autonomous agent), ensuring the correct file structure.</li></ol>',15)])])}const g=e(n,[["render",o]]);export{c as __pageData,g as default};
